#### P1160 队列安排
https://www.luogu.com.cn/problem/P1160
当需要节点之间前后顺序关系而又需要快速访问任意元素时，则需要**静态链表**数据结构
```cpp
using int64 = long long;
using intDB = double;

// 定义链表节点结构，使用数组模拟链表
struct node {
    int front;  // 前驱节点的编号
    int num;    // 当前节点的编号
    int next;   // 后继节点的编号
};

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int n;
    cin >> n;

    // 创建大小为n+2的数组模拟链表，0号和n+1号节点作为虚拟头尾节点
    vector<node> list(n + 2);

    // 初始化虚拟头节点0
    list[0].num = 0;
    list[0].next = 1;

    // 初始化第一个有效节点1
    list[1].num = 1;
    list[1].front = 0;
    list[1].next = n + 1;

    // 初始化虚拟尾节点n+1
    list[n + 1].front = list[1].num;
    list[n + 1].num = n + 1;

    // 插入2到n号节点
    for (int i = 2; i <= n; i++) {
        list[i].num = i;
        int k, p;
        cin >> k >> p;

        if (p == 0) { // 插入到k节点的左侧
            // 将i节点插入到k节点前
            list[list[k].front].next = list[i].num; // k的前驱的后继指向i
            list[i].front = list[k].front;          // i的前驱设为k的前驱
            list[i].next = list[k].num;             // i的后继设为k
            list[k].front = list[i].num;            // k的前驱设为i
        } else { // 插入到k节点的右侧
            // 将i节点插入到k节点后
            list[i].next = list[k].next;            // i的后继设为k的后继
            list[list[k].next].front = list[i].num; // k的后继的前驱设为i
            list[i].front = list[k].num;            // i的前驱设为k
            list[k].next = list[i].num;             // k的后继设为i
        }
    }

    // 处理删除操作
    int m;
    cin >> m;
    vector<int> states(n + 1, 1); // 标记节点是否被删除，1表示存在，0表示已删除
    while (m--) {
        int x;
        cin >> x;
        if (states[x] == 0) continue; // 已删除的节点直接跳过

        // 删除节点x：调整其前驱和后继节点的指针
        list[list[x].front].next = list[list[x].next].num; // x的前驱的后继指向x的后继
        list[list[x].next].front = list[list[x].front].num; // x的后继的前驱指向x的前驱
        states[x] = 0; // 标记节点x为已删除
    }

    // 遍历链表输出结果
    int i = list[0].next; // 从头节点的后继开始
    while (i != n + 1) {  // 直到遇到尾节点
        cout << list[i].num << " ";
        i = list[i].next; // 移动到下一个节点
    }

    return 0;
}
```
数组的 O1 用于查找节点对应的值，而链表记住前后关系

